package com.gymflex.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="memberships") public class Membership { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="member_id",unique=true) private Member member; @ManyToOne(optional=false) private Plan plan; private LocalDate startDate; private LocalDate endDate; public Membership(){} public Long getId(){return id;} public Member getMember(){return member;} public void setMember(Member v){member=v;} public Plan getPlan(){return plan;} public void setPlan(Plan v){plan=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} }